-- Rattrapage de tous les I_IdYanport deja en base. Ordre ecrit du 2026-10-09, complete le 2026-10-10.
-- Jonction intermediaires_directs_yanport : 2287/2287 (0 manquant). 387 lignes source 'saisi'.
-- Un INSERT dans cette table declenche un trigger qui met P_State=0 sur les biens deja lies.
-- Ce script n'insere plus de jonction. Il ajoute seulement les liens manquants des biens publies (P_State=1),
-- dealer en position 0 a 5 du JSON P_Annonceurs, egalite stricte sur l'id.
-- Inventaire SELECT du 2026-10-09 : 4444 couples (bien, agence) absents de rel_property_inter_direct.
-- 378 liens avaient deja ete ecrits juste avant (agence 573 : 118, biens dont l'id commence avant '1' : 260) et ne sont pas dans cette liste.
-- Le 2026-10-10, 142 de ces 4444 manquaient encore : INSERT IGNORE les a ajoutes. Controle : echantillon 202/202 present.
-- Agence 573 : 154 biens publies lies. Agence 6236 : 50 biens publies lies. Aucun bien reste a P_State<>1 sans date de fin.
-- Ids Yanport partages par deux agences, les deux cotes ont la jonction :
--   89573 = 960 et 961 ; 93836 = 898 et 5399 ; 5662077884563456 = 1846 et 3845.
-- La table bak_rel_yanport_rattrapage_20261009 n'a pas ete creee (DDL refuse).
-- Idempotent. Rollback = remplir cette table avec les VALUES puis le DELETE commente. Ne pas supprimer les lignes saisi : le trigger depublierait les biens lies.

CREATE TABLE IF NOT EXISTS bak_rel_yanport_rattrapage_20261009 (
  P_PropertyId varchar(40) NOT NULL,
  I_RefIntermediaire int(10) unsigned NOT NULL,
  PRIMARY KEY (P_PropertyId, I_RefIntermediaire)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
























SELECT P_PropertyId, I_RefIntermediaire FROM bak_rel_yanport_rattrapage_20261009;

